const SB_URL='https://opqbgwzmbkzkfpldrjlx.supabase.co';const SB_KEY='sb_publishable_nxQgwY7M--3zasV3UVzprw_nZXFBY8x';const sb=supabase.createClient(SB_URL,SB_KEY);
let user=null,tasks=[],filter='open',editing=null,calDate=new Date();
const $=id=>document.getElementById(id),fmt=d=>d?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00')):'Sin fecha';
const labels={pending:'Pendiente',in_progress:'En curso',waiting:'Esperando',done:'Terminado'},pri={low:'Baja',medium:'Media',high:'Alta',urgent:'Urgente'};
async function init(){const {data:{session}}=await sb.auth.getSession();if(session) await enter(session.user);sb.auth.onAuthStateChange((e,s)=>{if(e==='SIGNED_OUT')location.reload()})}
$('loginForm').onsubmit=async e=>{e.preventDefault();$('authMsg').textContent='';const {data,error}=await sb.auth.signInWithPassword({email:$('email').value,password:$('password').value});if(error)return $('authMsg').textContent=error.message;await enter(data.user)};
async function enter(u){user=u;$('auth').classList.add('hidden');$('app').classList.remove('hidden');$('userName').textContent=u.email;await loadTasks()}
$('logout').onclick=()=>sb.auth.signOut();
async function loadTasks(){const {data,error}=await sb.from('tasks').select('*,subtasks(id,title,is_done,sort_order),task_updates(id,body,update_type,created_at,author_id)').order('created_at',{ascending:false});if(error)return alert(error.message);tasks=data||[];render()}
function visible(t){const today=new Date().toISOString().slice(0,10);if(filter==='open')return t.status!=='done';if(filter==='mine')return t.owner_id===user.id||t.created_by===user.id;if(filter==='waiting')return t.status==='waiting';if(filter==='overdue')return t.status!=='done'&&t.due_date&&t.due_date<today;return true}
function render(){const list=tasks.filter(visible);$('summary').textContent=`${tasks.filter(t=>t.status!=='done').length} abiertas · ${tasks.filter(t=>t.status==='waiting').length} esperando · ${tasks.filter(t=>t.due_date&&t.due_date<new Date().toISOString().slice(0,10)&&t.status!=='done').length} vencidas`;$('taskGrid').innerHTML=list.length?list.map(card).join(''):'<div class="empty">No hay tareas en esta vista.</div>';document.querySelectorAll('.card').forEach(x=>x.onclick=()=>openTask(x.dataset.id));renderCalendar()}
function card(t){const done=t.subtasks.filter(s=>s.is_done).length,total=t.subtasks.length;return `<article class="card" data-id="${t.id}"><div class="card-top"><span class="badge status-${t.status}">${labels[t.status]}</span><b class="priority-${t.priority}">${pri[t.priority]}</b></div><h3>${esc(t.title)}</h3><p>${esc(t.description||'Sin descripción')}</p>${t.next_step?`<div class="next"><b>→ Próximo:</b> ${esc(t.next_step)}</div>`:''}<div class="meta"><span>☑ ${done}/${total}</span><span>📅 ${fmt(t.due_date)}</span></div></article>`}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;render()});
$('newTask').onclick=()=>openTask();function openTask(id){editing=id?tasks.find(t=>t.id===id):null;$('modalTitle').textContent=editing?'Editar tarea':'Nueva tarea';$('taskStatusBadge').textContent=editing?labels[editing.status]:'Nueva';$('taskTitle').value=editing?.title||'';$('taskDescription').value=editing?.description||'';$('taskStatus').value=editing?.status||'pending';$('taskPriority').value=editing?.priority||'medium';$('taskDue').value=editing?.due_date||'';$('taskFollow').value=editing?.follow_up_at?editing.follow_up_at.slice(0,16):'';$('taskNext').value=editing?.next_step||'';$('detailArea').classList.toggle('hidden',!editing);$('deleteTask').classList.toggle('hidden',!editing);$('taskMsg').textContent='';if(editing)renderDetail();$('taskDialog').showModal()}
$('saveTask').onclick=async()=>{if(!$('taskTitle').value.trim())return $('taskMsg').textContent='Poné un título.';const payload={title:$('taskTitle').value.trim(),description:$('taskDescription').value.trim(),status:$('taskStatus').value,priority:$('taskPriority').value,due_date:$('taskDue').value||null,follow_up_at:$('taskFollow').value?new Date($('taskFollow').value).toISOString():null,next_step:$('taskNext').value.trim()};let error;if(editing){({error}=await sb.from('tasks').update(payload).eq('id',editing.id))}else{payload.created_by=user.id;payload.owner_id=user.id;({error}=await sb.from('tasks').insert(payload))}if(error)return $('taskMsg').textContent=error.message;$('taskDialog').close();await loadTasks()};
$('deleteTask').onclick=async()=>{if(!editing||!confirm('¿Eliminar esta tarea y todo su seguimiento?'))return;const {error}=await sb.from('tasks').delete().eq('id',editing.id);if(error)return $('taskMsg').textContent=error.message;$('taskDialog').close();await loadTasks()};
function renderDetail(){const ss=[...editing.subtasks].sort((a,b)=>a.sort_order-b.sort_order);$('subtasks').innerHTML=ss.map(s=>`<label class="check"><input type="checkbox" data-sub="${s.id}" ${s.is_done?'checked':''}><span>${esc(s.title)}</span></label>`).join('')||'<small>No hay pasos todavía.</small>';document.querySelectorAll('[data-sub]').forEach(c=>c.onchange=async()=>{await sb.from('subtasks').update({is_done:c.checked,completed_at:c.checked?new Date().toISOString():null}).eq('id',c.dataset.sub);await refreshEditing()});const ups=[...editing.task_updates].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));$('updates').innerHTML=ups.map(u=>`<div class="event"><div>${esc(u.body)}</div><small>${new Date(u.created_at).toLocaleString('es-ES')}</small></div>`).join('')||'<small>Sin actualizaciones todavía.</small>'}
async function refreshEditing(){await loadTasks();editing=tasks.find(t=>t.id===editing.id);renderDetail()}
$('addSubtask').onclick=async()=>{const v=$('newSubtask').value.trim();if(!v)return;const {error}=await sb.from('subtasks').insert({task_id:editing.id,title:v,created_by:user.id,sort_order:editing.subtasks.length});if(error)return alert(error.message);$('newSubtask').value='';await refreshEditing()};
$('addUpdate').onclick=async()=>{const v=$('newUpdate').value.trim();if(!v)return;const {error}=await sb.from('task_updates').insert({task_id:editing.id,author_id:user.id,body:v});if(error)return alert(error.message);$('newUpdate').value='';await refreshEditing()};
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');const cal=b.dataset.view==='calendar';$('tasksView').classList.toggle('hidden',cal);$('filters').classList.toggle('hidden',cal);$('calendarView').classList.toggle('hidden',!cal);$('viewTitle').textContent=cal?'Calendario':'Tareas';renderCalendar()});
function renderCalendar(){const y=calDate.getFullYear(),m=calDate.getMonth();$('monthTitle').textContent=new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(calDate);const first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let out='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const dayTasks=tasks.filter(t=>t.due_date===iso);out+=`<div class="day ${d.getMonth()!==m?'muted':''}"><span class="daynum">${d.getDate()}</span>${dayTasks.map(t=>`<span class="cal-task" data-cal="${t.id}">${esc(t.title)}</span>`).join('')}</div>`} $('calendar').innerHTML=out;document.querySelectorAll('[data-cal]').forEach(x=>x.onclick=()=>openTask(x.dataset.cal))}
$('prevMonth').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()-1,1);renderCalendar()};$('nextMonth').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()+1,1);renderCalendar()};init();